<?php declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/includes/auth.php';$db=db();$e=fn($v)=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');if($_SERVER['REQUEST_METHOD']==='POST'){$n='EXP-'.date('Y').'-'.str_pad((string)((int)$db->query('SELECT COUNT(*) FROM expenses')->fetchColumn()+1),5,'0',STR_PAD_LEFT);$q=$db->prepare('INSERT INTO expenses(expense_number,client_id,project_id,category,description,amount,currency,expense_date,vendor_name,notes) VALUES(?,?,?,?,?,?,?,?,?,?)');$q->execute([$n,$_POST['client_id']?:null,$_POST['project_id']?:null,trim($_POST['category']),trim($_POST['description']??''),(float)$_POST['amount'],$_POST['currency']?:'USD',$_POST['expense_date'],trim($_POST['vendor_name']??''),trim($_POST['notes']??'')]);header('Location: expenses.php');exit;}$rows=$db->query('SELECT * FROM expenses ORDER BY expense_date DESC,id DESC')->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Expenses</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-4"><h1 class="h3">Expenses</h1><div class="card mb-4"><div class="card-body"><form method="post" class="row g-2"><div class="col-md-3"><input class="form-control" name="category" placeholder="Category" required></div><div class="col-md-3"><input class="form-control" name="vendor_name" placeholder="Vendor"></div><div class="col-md-2"><input class="form-control" type="number" step="0.01" name="amount" placeholder="Amount" required></div><div class="col-md-2"><input class="form-control" type="date" name="expense_date" value="<?=date('Y-m-d')?>" required></div><div class="col-md-2"><input class="form-control" name="currency" value="USD"></div><div class="col-md-6"><input class="form-control" name="description" placeholder="Description"></div><div class="col-md-3"><input class="form-control" type="number" name="client_id" placeholder="Client ID"></div><div class="col-md-3"><input class="form-control" type="number" name="project_id" placeholder="Project ID"></div><div class="col-12"><textarea class="form-control" name="notes" placeholder="Notes"></textarea></div><div class="col-12"><button class="btn btn-dark">Record Expense</button></div></form></div></div><div class="card"><div class="card-body"><table class="table"><thead><tr><th>Number</th><th>Category</th><th>Vendor</th><th>Date</th><th>Amount</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$e($r['expense_number'])?></td><td><?=$e($r['category'])?></td><td><?=$e($r['vendor_name'])?></td><td><?=$e($r['expense_date'])?></td><td><?=$e($r['currency'])?> <?=number_format((float)$r['amount'],2)?></td><td><?=$e($r['status'])?></td></tr><?php endforeach;?></tbody></table></div></div></main></body></html>